@_documentation(visibility: private)
#endif
public struct FfiConverterTypeFirstProofError: FfiConverterRustBuffer {
    typealias SwiftType = FirstProofError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> FirstProofError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .DatabaseError(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 2: return .DngError(
            reason: try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: FirstProofError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .DatabaseError(reason):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(reason, into: &buf)
            
        
        case let .DngError(reason):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(reason, into: &buf)
            
        }
    }
}


